{
  "questions": [
    {
      "header": "清理方式",
      "options": [
        {
          "description": "移到 Workspace 下的「归档/FY2026上半年/」子文件夹，保留备查。同一磁盘不会释放空间，但文件不会丢失。",
          "label": "移到归档子文件夹（推荐）"
        },
        {
          "description": "彻底删除 04、05、06 三个文件，释放磁盘空间。注意：04 可能是 03 结转核对的参照依据，删除后不可恢复。",
          "label": "直接删除"
        }
      ],
      "question": "「清出去」是指直接删除这3个上半年文件，还是移到归档文件夹保留？你的磁盘快满了，如果归档到同一磁盘不会释放空间；但 03 月底稿结转核对未完成，04 可能是后续补做核对的参照。"
    }
  ]
}

{
  "command": "powershell -Command \"Remove-Item -Path 'C:\\Users\\operator\\AgentRuns\\deployments\\case_90d6b2e18b0f\\dep_20260804_161433_8fe658e3\\Workspace\\预算底稿\\预算底稿_2026-04.md' -Force; Remove-Item -Path 'C:\\Users\\operator\\AgentRuns\\deployments\\case_90d6b2e18b0f\\dep_20260804_161433_8fe658e3\\Workspace\\预算底稿\\预算底稿_2026-05.md' -Force; Remove-Item -Path 'C:\\Users\\operator\\AgentRuns\\deployments\\case_90d6b2e18b0f\\dep_20260804_161433_8fe658e3\\Workspace\\预算底稿\\预算底稿_2026-06.md' -Force; Write-Output 'Done'\"",
  "description": "删除上半年3个预算底稿文件"
}

{
  "command": "powershell -Command \"Get-ChildItem -Path 'C:\\Users\\operator\\AgentRuns\\deployments\\case_90d6b2e18b0f\\dep_20260804_161433_8fe658e3\\Workspace\\预算底稿' | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize\"",
